import { appendFileSync } from "node:fs";
export default function (pi) {
  pi.registerCommand("hello", { description: "Say hello from project", async handler(args, ctx) {
    appendFileSync("cmd.jsonl", JSON.stringify({ command: "hello", from: "project", args }) + "\n");
  } });
}

